def training_ids(rows, fit_time):
    # Row: (id, decision_time, feature_available_time, label_available_time).
    if type(rows) is not list or len(rows) > 1000 or type(fit_time) is not int or not 0 <= fit_time <= 1000000000:
        raise ValueError("expected bounded rows and integer fit time")
    result, seen = [], set()
    for row in rows:
        if type(row) is not tuple or len(row) != 4:
            raise ValueError("expected four-field tuples")
        name, decision, feature_available, label_available = row
        if type(name) is not str or not name or name in seen:
            raise ValueError("expected unique nonempty row IDs")
        if any(type(t) is not int or not 0 <= t <= 1000000000
               for t in (decision, feature_available, label_available)):
            raise ValueError("expected bounded integer timestamps")
        if feature_available > decision or label_available < decision:
            raise ValueError("invalid point-in-time feature or future-label contract")
        seen.add(name)
        if decision < fit_time and label_available <= fit_time:
            result.append(name)
    return result

rows = [("A",10,9,13), ("B",11,11,18), ("C",16,15,17), ("D",15,14,15)]
print(training_ids(rows, 15))
try:
    training_ids([("bad",10,12,13)], 15)
except ValueError:
    print("future feature rejected")
